# -*- coding: utf-8 -*-
from lib import *

RS = ['white-label-account-recovery', 'how-white-label-account-recovery-works']

mk('when-to-turn-down-recovery-job', 'When to turn down a recovery job', 'ops',
 'When an Agency Should Turn Down a Recovery Request',
 'Some recovery requests should not be taken: no ownership, no go-ahead, requests to bend rules. A clear list helps an agency say no.',
 'When an agency should turn down a recovery request.',
 'A good partner tells you plainly when a request has no honest route. Here is when your agency should say no too.',
 'An agency should turn down a recovery request when the person asking does not own the account, the owner has not given a go-ahead, the account was bought or taken from someone else, the plan involves fake or mass reports, or the client wants a result promised. Saying no protects your agency.',
 [('Ownership first', 'No proof of ownership, no request.'),
  ('Rules matter', 'Anything that bends platform rules is out.'),
  ('Protect yourself', 'One bad job can cost a good client.')],
 [('list', 'Reasons to decline',
   TABLE(['Situation', 'Why decline'],
         [['The requester cannot show they own the account', 'You could help someone take another person’s account'],
          ['The owner has not agreed', 'The platform may need to contact the owner'],
          ['The account was bought or traded', 'Buying and selling accounts breaks the rules'],
          ['The plan involves fake or mass reports', 'It breaks the rules and can backfire'],
          ['The client wants a result promised', 'You cannot honestly give that promise'],
          ['The client wants to share a password with a stranger', 'It puts the account at risk']])),
  ('how', 'How to say no',
   TMPL('Short decline', 'I cannot take this on as described. I can only act for the account owner and only through the platform’s official routes. If you can show you own the account and want to proceed that way, I am happy to look at it again.')),
  ('gray', 'Grey areas',
   P('Sometimes ownership is shared, or the account was run for years by an agency that has since left. In those situations, ask for what proves the link to the business, and be willing to say that nothing can be done. A partner who is honest with you can tell you whether a route exists.')),
  ('partner', 'What your partner will do',
   P('Unbanz also declines requests that fall in these groups, and tells you why. See [[agency-account-recovery-red-flags|red flags for agencies]] for the provider side and [[account-recovery-sop-template-for-agencies|the SOP template]] to write the rule into your process.'))],
 [('Should an agency ever recover an account it does not own?', 'Only for the owner and with their go-ahead. Otherwise decline.'),
  ('What if the client bought the account?', 'Decline. Buying and selling accounts is against the rules and risky.'),
  ('What if the client insists on a promised result?', 'Explain that no one can promise it. If they insist, decline.'),
  ('Will Unbanz take every request?', 'No. We tell you plainly when a request has no honest route.'),
  ('How do I decline politely?', 'State what you can do, that you act only for the owner and only through official routes.')],
 RS + ['agency-account-recovery-red-flags', 'account-recovery-sop-template-for-agencies', 'client-terms-account-recovery-clause'],
 'When to say no to a recovery request, and how.')

mk('white-label-threads-account-recovery', 'White label Threads recovery', 'service',
 'White Label Threads Account Recovery for Agencies',
 'Threads accounts are tied to Instagram. How agencies can handle a client’s suspended Threads account under their own brand.',
 'White label Threads account recovery.',
 'A Threads suspension can look like an Instagram problem, or it can stand alone. Knowing which matters for the route.',
 'White label Threads account recovery lets an agency hand a client’s suspended or restricted Threads account to Unbanz while staying the only contact. Because Threads is linked to Instagram, the first step is to check whether the Instagram account is also affected. Meta decides, and no result can be promised.',
 [('Linked to Instagram', 'Check both accounts before you act.'),
  ('Stand-alone possible', 'Threads can be suspended while Instagram works.'),
  ('Your brand', 'Unbanz works behind the scenes.')],
 [('link', 'The link with Instagram',
   P('Threads accounts are created through Instagram. A problem on one can affect the other, but not always. The public pages [[/threads-account-suspended/|Threads account suspended]] and [[/threads-suspended-but-instagram-works/|Threads suspended but Instagram works]] explain the difference.')),
  ('check', 'What to check first',
   OL(['Does the Instagram account log in normally?', 'What does the Threads notice say, word for word?', 'When did it appear, and what was posted before?', 'Is the Threads profile used for business or brand work?'])),
  ('handoff', 'Handoff',
   P('Send the Threads username, the Instagram username, the notice screenshot and the date. Unbanz will tell you which route applies. See [[how-white-label-account-recovery-works|how white label recovery works]].')),
  ('expect', 'Expectations',
   P('The platform decides, and Threads decisions may follow their own rules. Tell the client plainly that you do not know the timing. Use [[client-status-update-templates-account-recovery|the status templates]] for updates.'))],
 [('Can an agency resell Threads recovery?', 'Yes. The agency stays the contact while Unbanz prepares the request behind the scenes.'),
  ('Does an Instagram problem always affect Threads?', 'Not always. Check both accounts and send the facts.'),
  ('Will the Threads account be restored?', 'No result can be promised. Meta decides.'),
  ('What do I send?', 'Both usernames, the Threads notice and the date.'),
  ('Does the client see Unbanz?', 'No.')],
 RS + ['white-label-instagram-account-recovery', 'white-label-recovery-for-social-media-agencies', 'client-status-update-templates-account-recovery'],
 'Threads recovery for agencies: the Instagram link, checks and handoff.')

mk('account-recovery-incident-report-template-for-agencies', 'Recovery incident report template', 'ops',
 'Account Recovery Incident Report Template',
 'A simple report your agency can send a client after a recovery request closes: timeline, outcome, next steps and prevention.',
 'Account recovery incident report template.',
 'A short written report after each incident shows professionalism and protects you if questions come later.',
 'An account recovery incident report records what happened, what was done, the platform’s decision and the next steps. Send one to the client when a request closes. It should be factual and short, state that the platform decided, and avoid blame. Below is a template you can copy.',
 [('Short and factual', 'One page is enough.'),
  ('Protects you', 'A record of what was done and when.'),
  ('Ends with prevention', 'Next steps stop a repeat.')],
 [('template', 'The template',
   TMPL('Incident report', 'Account: username and platform.', 'Date the notice appeared: date.', 'What the notice said: short quote.', 'Actions taken, with dates: request started, request filed, any client action needed.', 'Decision from the platform: restored, not restored, or still waiting, and the date.', 'Next steps: what we recommend now.', 'Prevention: admins, recovery email, authenticator app, backup codes.')),
  ('tips', 'Tips for writing it',
   UL(['Use dates, not feelings.', 'Do not blame the client or the platform.', 'Do not mention the partner unless you choose to.', 'State that the platform made the final decision.'])),
  ('use', 'How agencies use it',
   P('The report goes to the client when the matter closes and is stored in the matter folder. It also feeds your quarterly review of what went wrong and what to change, using [[prevent-client-account-lockouts-agency-checklist|the prevention checklist]].')),
  ('link', 'Related',
   P('Pair it with [[client-status-update-templates-account-recovery|the status templates]] and [[account-recovery-sop-template-for-agencies|the SOP template]].'))],
 [('Why send an incident report?', 'It gives the client a clear record and shows professional handling.'),
  ('How long should it be?', 'One page is enough.'),
  ('Should I name the recovery partner?', 'That is your choice.'),
  ('Should I include the platform’s emails?', 'Quote the relevant lines. Do not forward private emails in full.'),
  ('Can I copy the template?', 'Yes.')],
 RS + ['client-status-update-templates-account-recovery', 'account-recovery-sop-template-for-agencies', 'prevent-client-account-lockouts-agency-checklist'],
 'A short incident report template to send when a request closes.')

mk('client-account-security-audit-agency-service', 'Account security audit service', 'ops',
 'Account Security Audit as an Agency Service',
 'How an agency can package an account security audit for clients: what to check, how to report and how it leads to recovery support.',
 'Account security audit as an agency service.',
 'Clients rarely think about account security until something breaks. An audit gives you a natural reason to talk to them first.',
 'An account security audit is a short check of who owns a client’s accounts, who has access, how login is protected and whether recovery details are current. Agencies can sell it as a one-off or a quarterly service. It reduces risk without promising any outcome, and recovery support sits alongside it.',
 [('Proactive', 'Raise the issue before the client has a problem.'),
  ('Simple scope', 'Ownership, access, login protection, records.'),
  ('Honest', 'It reduces risk. It does not remove it.')],
 [('scope', 'What an audit covers',
   TABLE(['Area', 'What you check'],
         [['Ownership', 'Who owns the business portfolio, Pages and ad accounts'],
          ['Access', 'Admins, editors, old agencies and collaborators'],
          ['Login protection', 'Authenticator app, backup codes'],
          ['Recovery details', 'Email on the client’s domain, current phone number'],
          ['Account health', 'Account Quality notices, payment and verification'],
          ['Records', 'Where notices and dates are kept']])),
  ('deliver', 'What the client receives',
   UL(['A short report listing what is in place and what is missing.', 'A list of fixes, in order.', 'A note on what to do if an account is locked, including who to call.']) +
   P('The working list is the [[prevent-client-account-lockouts-agency-checklist|prevention checklist]].')),
  ('sell', 'How to sell it',
   P('Position it as care, not fear. A one-off audit at onboarding and a short review each quarter fit most retainers. Do not use scare tactics and do not claim it will stop a platform decision. See [[agency-pricing-models-reselling-recovery|pricing models]].')),
  ('lead', 'How it leads to recovery support',
   P('An audit shows clients where they are exposed and makes the recovery service easier to understand. Clients who know the process before a lockout are calmer during one. See [[white-label-account-recovery|white label account recovery]].'))],
 [('What is an account security audit?', 'A short check of ownership, access, login protection and recovery details for a client’s accounts.'),
  ('Does an audit prevent lockouts?', 'It reduces the risk and the damage. It cannot stop a platform decision.'),
  ('Does the audit need access to passwords?', 'No. Use the platform’s own settings screens with the client.'),
  ('How often should I run it?', 'At onboarding and once a quarter is a sensible rhythm.'),
  ('Does Unbanz run the audit?', 'No. The audit is your service. Recovery support is where Unbanz comes in.')],
 RS + ['prevent-client-account-lockouts-agency-checklist', 'agency-pricing-models-reselling-recovery', 'white-label-recovery-for-web-design-seo-agencies'],
 'Package an account security audit and link it to recovery support.')
